        var style = // Style function
        function style(a) {
            var s = ' style="';
            if (a && typeof a.style != "undefined") {
                s += a.style + ";";
            }
            s += '" ';
            return s;
        };
        // If filename is not defined then output to the result
        if (typeof filename == "object") {
            opts = filename;
            filename = undefined;
        }
        // Set sheets
        var sheets = {};
        if (opts && opts.sheets) {
            sheets = opts.sheets;
        }
        // Default sheet
        var sheet = {
            headers: true
        };
        if (typeof sheets["Sheet1"] != "undefined") {
            sheet = sheets[0];
        } else {
            if (typeof opts != "undefined") {
                sheet = opts;
            }
        }
